#!/usr/bin/python
import sys


def reject(message):
    sys.stderr.write('total.py: %s\n' % message)
    return 1


def main(argv):
    if len(argv) != 2:
        return reject('usage: total.py COUNTERS_FILE')

    try:
        counters = open(argv[1], 'r')
    except IOError, error:
        return reject(str(error))

    total = 0L
    line_number = 0
    try:
        for line in counters:
            line_number += 1
            record = line.strip()
            if not record or not record.isdigit():
                return reject('invalid counter on line %d' % line_number)
            try:
                value = long(record, 10)
            except ValueError:
                return reject('invalid counter on line %d' % line_number)
            if value < 0:
                return reject('negative counter on line %d' % line_number)
            total += value
    finally:
        counters.close()

    sys.stdout.write(str(total) + '\n')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
